package com.example.kpkn.data.models

import java.text.Normalizer

/**
 * A curated mobility movement. The public name and editorial copy are Spanish;
 * aliases are intentionally kept out of the UI and are only used for search
 * compatibility with familiar international terms.
 */
data class MobilityExercise(
    val id: String,
    val name: String,
    val discomfortIds: List<String>,
    val description: String,
    val durationSeconds: Int = 60,
    /** Stable internal region key used by the live-workout resolver. */
    val bodyRegion: String,
    val category: String = "Movilidad",
    val instructions: String? = null,
    val aliases: List<String> = emptyList(),
    val joints: List<String> = emptyList(),
    val targetMuscles: List<String> = emptyList(),
    val objective: String = "Mejorar el control y el rango disponible.",
    val equipment: String = "Sin material",
    val level: String = "Inicial",
    val precautions: String = DEFAULT_PRECAUTIONS,
) {
    companion object {
        const val DEFAULT_PRECAUTIONS =
            "Trabaja sin dolor agudo y detén el movimiento si pierdes el control."
    }
}

/** Visible labels for the stable internal keys used by workout routing. */
fun mobilityBodyRegionLabel(value: String): String = when (value.lowercase()) {
    "neck" -> "Cuello"
    "shoulder" -> "Hombro"
    "scapula" -> "Escápula"
    "upper" -> "Espalda alta"
    "spine" -> "Columna"
    "trunk" -> "Tronco"
    "elbow" -> "Codo y antebrazo"
    "wrist" -> "Muñeca y mano"
    "hip" -> "Cadera"
    "pelvis" -> "Pelvis"
    "leg" -> "Muslo y glúteo"
    "knee" -> "Rodilla"
    "ankle" -> "Tobillo"
    "foot" -> "Pie"
    else -> value.replace('_', ' ').lowercase().replaceFirstChar { it.uppercase() }
}

private fun normalizeMobilitySearch(value: String): String =
    Normalizer.normalize(value.trim().lowercase(), Normalizer.Form.NFD)
        .replace("\\p{Mn}+".toRegex(), "")
        .replace("[^a-z0-9]+".toRegex(), " ")
        .trim()

private fun movement(
    id: String,
    name: String,
    discomfortIds: List<String>,
    bodyRegion: String,
    joints: List<String>,
    targetMuscles: List<String>,
    objective: String,
    description: String,
    instructions: String,
    durationSeconds: Int = 45,
    aliases: List<String> = emptyList(),
    equipment: String = "Sin material",
    level: String = "Inicial",
    precautions: String = MobilityExercise.DEFAULT_PRECAUTIONS,
    category: String = "Movilidad",
) = MobilityExercise(
    id = id,
    name = name,
    discomfortIds = discomfortIds,
    description = description,
    durationSeconds = durationSeconds,
    bodyRegion = bodyRegion,
    category = category,
    instructions = instructions,
    aliases = aliases,
    joints = joints,
    targetMuscles = targetMuscles,
    objective = objective,
    equipment = equipment,
    level = level,
    precautions = precautions,
)

