        movement("mob_finger_spread", "Apertura y cierre de dedos", listOf("wrist_hand"), "wrist", listOf("metacarpofalángicas", "interfalángicas"), listOf("intrínsecos de la mano"), "Recuperar separación y coordinación de los dedos", "Alternar puño suave y mano abierta moviliza las articulaciones pequeñas sin convertir el gesto en un apretón fuerte.", "Abre los dedos uno a uno, forma un puño relajado y vuelve a extenderlos; presta atención al pulgar.", 30, listOf("finger spread")),
        movement("mob_wrist_mobilization", "Movilización de muñeca en cuatro direcciones", listOf("wrist_hand"), "wrist", listOf("muñeca"), listOf("flexores y extensores de muñeca"), "Recorrer flexión, extensión y desviaciones con apoyo dosificado", "El apoyo de la otra mano guía la muñeca sin comprimirla; cada dirección se trabaja por separado para identificar el límite.", "Sujeta la mano y explora cuatro direcciones durante 5 segundos cada una, manteniendo el antebrazo relajado.", 45, listOf("four way wrist mobilization")),
        movement("mob_quadruped_wrist_rock_back", "Balanceo de muñeca hacia atrás", listOf("wrist_hand"), "wrist", listOf("muñeca", "codo"), listOf("flexores de muñeca"), "Preparar la extensión de muñeca para apoyos", "El desplazamiento de cadera regula la carga y permite encontrar la extensión disponible sin colapsar los dedos.", "En cuatro apoyos con dedos hacia delante, lleva la cadera atrás hasta notar tensión tolerable y regresa manteniendo los nudillos activos.", 40, listOf("wrist rock back")),
        movement("mob_quadruped_wrist_fingers_back", "Balanceo con dedos hacia las rodillas", listOf("wrist_hand", "elbow_medial"), "wrist", listOf("muñeca", "codo"), listOf("flexores de muñeca y dedos"), "Explorar extensión con antebrazo supinado", "Cambiar la orientación de los dedos modifica la tensión de la cadena flexora y requiere menos recorrido que un estiramiento pasivo.", "Apoya las palmas con dedos hacia las rodillas, desplaza el peso unos centímetros y vuelve; mantén los codos suaves.", 35, listOf("fingers back wrist stretch"), precautions = "Reduce el peso inmediatamente si aparece hormigueo o dolor eléctrico."),
        movement("mob_reverse_prayer", "Oración inversa de muñecas", listOf("wrist_hand", "elbow_lateral"), "wrist", listOf("muñeca"), listOf("extensores de muñeca"), "Mejorar extensión activa y tolerancia al estiramiento", "Las palmas juntas detrás del cuerpo permiten una carga simétrica y fácil de graduar separando las manos.", "Junta los dorsos de las manos detrás de la espalda y elévalos solo hasta sentir tensión suave; respira sin encorvarte.", 30, listOf("reverse prayer stretch"), precautions = "No juntes las manos a la fuerza ni mantengas los hombros elevados."),
        movement("mob_tendon_glides", "Deslizamientos tendinosos de la mano", listOf("wrist_hand"), "wrist", listOf("interfalángicas", "metacarpofalángicas"), listOf("flexores de dedos"), "Mover los tendones por distintas posiciones de la mano", "La secuencia alterna mano recta, garra, puño completo y puño plano para cambiar la tensión de cada tendón.", "Realiza cada forma durante 3 segundos, sin apretar, y vuelve a abrir la mano por completo entre posiciones.", 60, listOf("tendon glides")),
        movement("mob_thumb_opposition", "Oposición activa del pulgar", listOf("wrist_hand"), "wrist", listOf("trapeciometacarpiana", "metacarpofalángica"), listOf("oponente del pulgar", "aductor del pulgar"), "Mejorar precisión y movilidad del pulgar", "Tocar la base de cada dedo combina oposición, flexión y rotación sin necesitar una carga externa.", "Toca con el pulgar la base del meñique y vuelve a cada dedo, manteniendo la palma abierta y el movimiento lento.", 35, listOf("thumb opposition")),
        movement("mob_radial_ulnar_deviation", "Desviaciones radial y cubital", listOf("wrist_hand"), "wrist", listOf("muñeca"), listOf("flexor radial", "extensor cubital"), "Recuperar el movimiento lateral de la muñeca", "La mano se desplaza hacia el pulgar y hacia el meñique con el antebrazo estable, evitando girar todo el brazo.", "Apoya el antebrazo en la mesa y mueve la mano de lado a lado como un limpiaparabrisas; mantén los dedos sueltos.", 35, listOf("radial ulnar deviation")),

        // Columna torácica, lumbar y pelvis -----------------------------------------
        movement("mob_thoracic_extension", "Extensión torácica sobre rodillo", listOf("upper_back"), "upper", listOf("torácica"), listOf("extensores torácicos", "pectoral"), "Recuperar extensión en la espalda alta", "El rodillo sirve de fulcro en la zona torácica y permite extender sin pedir una hiperextensión lumbar.", "Coloca el rodillo bajo la espalda alta, sujeta la cabeza y extiende sobre él al exhalar; cambia de nivel unos centímetros.", 60, listOf("thoracic extension foam roller"), equipment = "Rodillo", precautions = "No lleves el rodillo a la zona lumbar ni dejes caer la cabeza sin sostén."),
        movement("mob_open_book", "Rotación torácica en decúbito lateral", listOf("upper_back"), "upper", listOf("torácica", "escapulotorácica"), listOf("oblicuos", "pectoral"), "Aumentar rotación sin mover la pelvis", "Las rodillas apiladas bloquean la pelvis para que el giro provenga de la espalda alta y no de una torsión lumbar.", "De lado con rodillas a 90 grados, abre el brazo superior siguiendo la mano con la mirada y vuelve manteniendo las rodillas juntas.", 45, listOf("open book stretch")),
        movement("mob_scapular_retraction", "Retracción escapular con banda", listOf("upper_back", "shoulder_posterior"), "upper", listOf("escapulotorácica"), listOf("romboides", "trapecio medio"), "Practicar la posición de la escápula sin rigidez", "La banda ofrece una referencia de tensión continua, pero el objetivo es deslizar los omóplatos hacia atrás y abajo sin sacar el pecho.", "Tira de la banda hasta que los brazos queden alineados con el tronco, pausa un segundo y vuelve sin encoger los hombros.", 45, listOf("band scapular retraction"), equipment = "Banda elástica"),
        movement("mob_cat_cow", "Ondulación de columna en cuatro apoyos", listOf("lumbar", "upper_back"), "spine", listOf("torácica", "lumbar"), listOf("erectores espinales", "abdominales"), "Distribuir flexión y extensión por toda la columna", "La columna se mueve de manera segmentada, desde la pelvis hasta la cabeza, evitando convertir el gesto en un balanceo rápido de la lumbar.", "Desde cuatro apoyos, mete la pelvis y redondea vértebra a vértebra; luego invierte el movimiento sin colgar el abdomen.", 60, listOf("cat cow")),
        movement("mob_pelvic_tilts", "Basculaciones pélvicas supinas", listOf("lumbar", "hip_front"), "pelvis", listOf("lumbar", "coxofemoral"), listOf("abdominales", "glúteo mayor"), "Diferenciar pelvis y columna lumbar", "El gesto alterna una ligera impresión y liberación de la zona lumbar para aprender a mover la pelvis sin empujar con las piernas.", "Boca arriba con rodillas flexionadas, acerca el pubis al esternón y luego relaja hasta recuperar el arco natural; respira de forma continua.", 45, listOf("pelvic tilts")),
        movement("mob_child_pose_rotation", "Postura de descanso con alcance lateral", listOf("lumbar", "upper_back"), "spine", listOf("torácica", "lumbar", "hombro"), listOf("dorsal ancho", "oblicuos"), "Combinar flexión cómoda y apertura costal", "El alcance hacia un lado cambia la tensión entre dorsal, costillas y pelvis, por lo que cada lado se trabaja por separado.", "Desde talones atrás, camina las manos hacia un lado y respira hacia las costillas opuestas; vuelve al centro antes de cambiar.", 60, listOf("child's pose rotation")),
        movement("mob_quadruped_thoracic_rotation", "Rotación torácica con mano en nuca", listOf("upper_back", "lumbar"), "upper", listOf("torácica", "escapulotorácica"), listOf("oblicuos", "romboides"), "Aislar la rotación de la espalda alta", "El codo dibuja un arco mientras la pelvis se mantiene nivelada; el movimiento no busca llevar el codo al techo a cualquier precio.", "Coloca una mano en la nuca, rota el codo hacia arriba y vuelve a apuntar al suelo sin desplazar la cadera.", 45, listOf("quadruped thoracic rotation")),
        movement("mob_seated_thoracic_rotation", "Rotación torácica sentada", listOf("upper_back"), "upper", listOf("torácica"), listOf("oblicuos", "multífidos"), "Recuperar giro para mirar detrás sin compensar", "Cruzar los brazos sobre el pecho elimina el impulso y deja que la pelvis sirva de base estable.", "Siéntate erguido, cruza los brazos y gira desde las costillas hasta donde puedas mantener ambos isquiones apoyados.", 40, listOf("seated thoracic rotation")),
        movement("mob_wall_thoracic_extension", "Extensión torácica en pared", listOf("upper_back"), "upper", listOf("torácica", "escapulotorácica"), listOf("extensores torácicos", "serrato anterior"), "Extender la espalda alta en bipedestación", "La pared ofrece una referencia vertical para que la pelvis no se desplace mientras el pecho se abre.", "Apoya manos y antebrazos en la pared, lleva el pecho entre los brazos y vuelve al apilar las costillas sobre la pelvis.", 45, listOf("wall thoracic extension")),
        movement("mob_segmental_rollback", "Enrollamiento segmentado sentado", listOf("lumbar"), "spine", listOf("lumbar", "torácica"), listOf("abdominales", "erectores espinales"), "Controlar la flexión de columna por segmentos", "Bajar lentamente desde la cabeza hasta la pelvis mejora la percepción del movimiento y evita caer de golpe sobre la zona lumbar.", "Siéntate con rodillas flexionadas, mete la pelvis y rueda hacia atrás hasta donde mantengas control; regresa apilando la columna.", 45, listOf("segmental rollback"), level = "Intermedio"),
        movement("mob_prone_press_up", "Extensión lumbar progresiva", listOf("lumbar"), "spine", listOf("lumbar", "coxofemoral"), listOf("erectores espinales", "recto abdominal"), "Explorar extensión lumbar sin cargar los hombros", "Los brazos solo asisten; la pelvis permanece pesada y el rango se detiene antes de que aparezca compresión localizada.", "Boca abajo, apoya antebrazos y eleva el pecho suavemente; mantén la pelvis en el suelo y vuelve al exhalar.", 40, listOf("press up"), precautions = "No uses este movimiento si la extensión aumenta dolor irradiado o síntomas neurológicos."),
        movement("mob_90_90_breathing", "Respiración 90/90 con pelvis neutra", listOf("lumbar", "hip_front"), "pelvis", listOf("lumbar", "coxofemoral"), listOf("diafragma", "abdominales", "flexores de cadera"), "Organizar pelvis y caja torácica antes de moverse", "La posición de caderas y rodillas reduce la demanda de los flexores y facilita una exhalación que apila las costillas sobre la pelvis.", "Boca arriba con piernas sobre una silla, exhala hasta sentir el abdomen activo y vuelve a inhalar expandiendo los costados.", 60, listOf("90 90 breathing"), equipment = "Silla"),
        movement("mob_dead_bug_reach", "Alcance supino con talones apoyados", listOf("lumbar"), "trunk", listOf("lumbar", "hombro"), listOf("abdominales", "serrato anterior"), "Mantener la columna mientras se mueve el hombro", "El alcance de brazos y el apoyo de los pies desafían la estabilidad sin exigir velocidad ni carga externa.", "Boca arriba con caderas y rodillas flexionadas, alcanza los brazos al techo y alterna un brazo atrás sin despegar las costillas.", 45, listOf("dead bug reach"), level = "Intermedio"),
        movement("mob_pelvic_clock", "Reloj pélvico", listOf("lumbar", "hip_front"), "pelvis", listOf("lumbar", "sacroilíaca"), listOf("abdominales", "glúteos"), "Explorar inclinaciones pélvicas pequeñas", "Imaginar un reloj bajo la pelvis permite diferenciar inclinación anterior, posterior y lateral con un recorrido muy pequeño.", "Boca arriba, mueve el pubis hacia las 12, luego hacia las 6 y finalmente hacia cada cadera sin que las piernas participen.", 45, listOf("pelvic clock")),

        // Cadera, pelvis, aductores y cadena posterior -------------------------------
        movement("mob_couch_stretch", "Estiramiento de cadera anterior en apoyo", listOf("hip_front"), "hip", listOf("coxofemoral", "rodilla"), listOf("recto femoral", "psoas ilíaco"), "Abrir extensión de cadera sin arquear la lumbar", "La rodilla flexionada pone al recto femoral en tensión y el apoyo permite regular la intensidad acercando o alejando la pelvis.", "Coloca el empeine en un sofá o pared, adelanta la otra pierna y lleva el pubis hacia delante manteniendo las costillas abajo.", 60, listOf("couch stretch"), equipment = "Pared o sofá", precautions = "Reduce la profundidad si aparece dolor anterior de rodilla o compresión lumbar."),
        movement("mob_hip_flexor_lunge", "Zancada de flexor de cadera", listOf("hip_front"), "hip", listOf("coxofemoral", "lumbar"), listOf("psoas ilíaco", "recto femoral", "glúteo mayor"), "Recuperar extensión de cadera en bipedestación", "La retroversión pélvica es la clave: evita que la sensación de extensión provenga de arquear la espalda.", "En media rodilla, aprieta el glúteo de la pierna atrasada, lleva la pelvis unos centímetros al frente y alcanza el brazo del mismo lado.", 45, listOf("hip flexor lunge")),
        movement("mob_90_90_hip", "Transiciones de cadera 90/90", listOf("hip_front", "hip_lateral"), "hip", listOf("coxofemoral"), listOf("rotadores internos y externos de cadera"), "Alternar rotación interna y externa con control", "Las piernas en 90/90 convierten el cambio de lado en una exploración activa de ambas caderas, no en un giro de rodillas por inercia.", "Sentado, cambia las rodillas de un lado al otro manteniendo los pies pesados; inclínate solo si puedes conservar la pelvis estable.", 60, listOf("90/90 hip switch"), level = "Intermedio", precautions = "Apoya las manos o reduce el ángulo si la rodilla interna recibe presión."),
        movement("mob_hip_car", "Círculo articular controlado de cadera", listOf("hip_front", "hip_lateral"), "hip", listOf("coxofemoral", "pelvis"), listOf("glúteos", "psoas", "rotadores profundos"), "Mapear el rango activo de la cadera", "La pierna describe un círculo amplio mientras el tronco permanece quieto; cada fase revela una parte distinta del rango.", "De pie con apoyo, eleva la rodilla, abre, extiende hacia atrás y regresa por el centro en 8 segundos.", 50, listOf("hip CAR", "controlled articular rotation"), level = "Intermedio", precautions = "Usa apoyo para no convertir el ejercicio en una inclinación del tronco."),
        movement("mob_clamshell", "Apertura lateral de cadera", listOf("hip_lateral"), "hip", listOf("coxofemoral"), listOf("glúteo medio", "glúteo menor"), "Activar abductores sin girar la pelvis", "El movimiento es pequeño y nace de la cadera; mantener los talones juntos no sirve si el tronco rueda hacia atrás.", "De lado con rodillas flexionadas, abre la rodilla superior sin separar los pies y baja en tres segundos.", 45, listOf("clamshell")),
        movement("mob_fire_hydrant", "Abducción de cadera en cuatro apoyos", listOf("hip_lateral"), "hip", listOf("coxofemoral", "lumbar"), listOf("glúteo medio", "rotadores profundos"), "Controlar la abducción con pelvis nivelada", "La rodilla se aleja del cuerpo mientras la pelvis permanece paralela al suelo, evitando una rotación lumbar.", "Desde cuatro apoyos, eleva una rodilla hacia el costado hasta donde no se incline la pelvis; desciende lentamente.", 45, listOf("fire hydrant")),
        movement("mob_hip_circle_standing", "Círculos de cadera de pie", listOf("hip_lateral"), "hip", listOf("coxofemoral", "pelvis"), listOf("glúteos", "flexores de cadera"), "Lubricar el recorrido global de la cadera", "El apoyo externo permite dibujar círculos amplios sin utilizar el tronco para ganar amplitud.", "Sujétate a una pared, flexiona una rodilla y dibuja círculos con la rodilla en ambos sentidos; cambia de pierna.", 45, listOf("standing hip circles")),
        movement("mob_adductor_rockback", "Balanceo de aductor hacia atrás", listOf("adductor_groin"), "hip", listOf("coxofemoral", "rodilla"), listOf("aductores", "isquiosurales"), "Explorar abducción y flexión de cadera", "Una pierna extendida al costado permite que la cadera se desplace hacia atrás sin convertir el estiramiento en una apertura forzada.", "Desde cuatro apoyos, extiende una pierna lateral con el pie apoyado y lleva la pelvis atrás hasta notar tensión interna tolerable.", 45, listOf("adductor rockback")),
        movement("mob_frog_stretch", "Apertura de aductores en rana", listOf("adductor_groin"), "hip", listOf("coxofemoral", "rodilla"), listOf("aductores", "suelo pélvico"), "Aumentar abducción de cadera con apoyo simétrico", "Las rodillas se separan mientras los pies quedan alineados con ellas; el rango se dosifica con la distancia de las rodillas y la profundidad.", "En cuatro apoyos, abre las rodillas y lleva la cadera atrás solo hasta sentir tensión amplia, no dolor puntual.", 60, listOf("frog stretch"), precautions = "No rebotes ni fuerces la apertura si existe dolor inguinal o sensación de inestabilidad."),
        movement("mob_side_lunge_adductor", "Zancada lateral para aductores", listOf("adductor_groin", "knee_medial"), "hip", listOf("coxofemoral", "rodilla"), listOf("aductores", "glúteo medio"), "Cargar una cadera mientras la otra se alarga", "La pierna flexionada recibe el peso y la pierna extendida permite explorar longitud del aductor con el pie completo apoyado.", "Da un paso lateral, lleva la cadera hacia atrás sobre la pierna flexionada y conserva la otra rodilla extendida sin colapsar el pie.", 45, listOf("side lunge adductor"), level = "Intermedio"),
        movement("mob_butterfly_stretch", "Apertura en mariposa", listOf("adductor_groin"), "hip", listOf("coxofemoral"), listOf("aductores", "rotadores externos"), "Relajar la aducción con una postura estable", "El peso de las piernas aporta una tensión gradual; no es necesario presionar las rodillas para obtener un estímulo útil.", "Siéntate con plantas juntas, alarga la espalda y deja caer las rodillas mientras exhalas; inclínate solo desde la cadera.", 45, listOf("butterfly stretch")),
        movement("mob_supported_deep_squat", "Sentadilla profunda asistida", listOf("hip_front", "adductor_groin", "ankle"), "hip", listOf("coxofemoral", "rodilla", "tobillo"), listOf("glúteos", "aductores", "sóleo"), "Integrar cadera, rodilla y tobillo en flexión", "El apoyo descarga parte del peso para explorar profundidad manteniendo los pies y la columna organizados.", "Sujeta un poste, desciende entre los talones y respira abajo; empuja el suelo para volver sin perder las rodillas sobre los pies.", 60, listOf("supported deep squat"), equipment = "Poste o soporte", level = "Intermedio"),
        movement("mob_deep_squat_pry", "Movilización de sentadilla profunda", listOf("hip_front", "adductor_groin", "ankle"), "hip", listOf("coxofemoral", "rodilla", "tobillo"), listOf("aductores", "glúteos", "sóleo"), "Explorar pequeños desplazamientos dentro de la sentadilla", "Los codos separan suavemente las rodillas mientras el cuerpo se mueve hacia ambos lados, distribuyendo el rango entre varias articulaciones.", "En sentadilla profunda con apoyo si hace falta, desplaza el peso de un pie al otro sin despegar talones ni colapsar las rodillas.", 45, listOf("squat pry"), level = "Intermedio"),
        movement("mob_hip_airplane", "Avión de cadera asistido", listOf("hip_lateral"), "hip", listOf("coxofemoral", "pelvis"), listOf("glúteo medio", "rotadores profundos"), "Entrenar rotación de pelvis sobre una pierna", "La pierna de apoyo estabiliza y el tronco gira como una unidad; el apoyo de una mano permite priorizar control sobre equilibrio.", "Inclínate sobre una pierna con la pelvis cuadrada, abre y cierra la cadera lentamente y vuelve a erguirte.", 45, listOf("hip airplane"), level = "Avanzado", precautions = "Hazlo junto a una pared y detén el ejercicio si la rodilla pierde alineación."),
        movement("mob_pigeon_supported", "Estiramiento de glúteo en apoyo", listOf("hip_lateral"), "hip", listOf("coxofemoral"), listOf("glúteo mayor", "rotadores externos"), "Explorar flexión y rotación externa de cadera", "El apoyo bajo la pelvis reduce la torsión y permite encontrar una posición simétrica para la cadera.", "Coloca una pierna flexionada delante con apoyo bajo la pelvis, alarga la espalda y lleva el pecho hacia delante sin hundir la cadera.", 60, listOf("pigeon stretch"), equipment = "Cojín o bloque", precautions = "No fuerces la rodilla; ajusta el pie y eleva la pelvis si la tensión se concentra en la articulación."),
        movement("mob_figure_four_supine", "Figura cuatro supina", listOf("hip_lateral"), "hip", listOf("coxofemoral"), listOf("glúteo mayor", "piriforme"), "Movilizar la cadera con la espalda apoyada", "El suelo limita la compensación lumbar y permite graduar el estiramiento acercando los muslos al pecho.", "Cruza un tobillo sobre la rodilla contraria, sujeta el muslo de apoyo y acércalo hasta sentir tensión en el glúteo.", 45, listOf("figure four stretch")),
        movement("mob_supine_windshield_wipers", "Limpiaparabrisas de cadera", listOf("hip_lateral", "hip_front"), "hip", listOf("coxofemoral", "pelvis"), listOf("rotadores internos y externos"), "Alternar rotación interna y externa en descarga", "Las piernas flexionadas permiten que ambas caderas roten juntas y que el rango sea fácil de reducir.", "Boca arriba con rodillas flexionadas, deja caer ambas piernas a un lado y al otro manteniendo hombros y pies relajados.", 45, listOf("windshield wipers")),
        movement("mob_internal_rotation_lift", "Elevación activa de rotación interna", listOf("hip_front", "hip_lateral"), "hip", listOf("coxofemoral"), listOf("glúteo medio", "rotadores internos"), "Fortalecer el control del final de rotación interna", "La pierna se mantiene apoyada mientras el pie se eleva, creando una contracción corta sin empujar la cadera hacia atrás.", "Sentado con rodillas flexionadas, deja los pies juntos y eleva un pie sin separar la rodilla del otro; baja despacio.", 40, listOf("hip internal rotation lift"), level = "Intermedio"),
        movement("mob_external_rotation_lift", "Elevación activa de rotación externa", listOf("hip_lateral"), "hip", listOf("coxofemoral"), listOf("rotadores externos", "glúteo medio"), "Mejorar control de rotación externa", "La rodilla permanece alineada mientras el pie se separa, evitando que el movimiento provenga de girar toda la pelvis.", "Sentado con pies separados, eleva un pie hacia dentro manteniendo la rodilla en su sitio y vuelve con control.", 40, listOf("hip external rotation lift"), level = "Intermedio"),
        movement("mob_half_kneeling_lateral_reach", "Alcance lateral en media rodilla", listOf("hip_front", "adductor_groin"), "pelvis", listOf("coxofemoral", "torácica"), listOf("psoas", "oblicuos", "aductores"), "Abrir la línea lateral manteniendo la pelvis estable", "El brazo alcanza por encima mientras la cadera de la pierna atrasada permanece extendida, combinando flexión lateral y extensión de cadera.", "En media rodilla, aprieta el glúteo de atrás y alcanza hacia el lado contrario sin desplazar la pelvis.", 45, listOf("half kneeling lateral reach")),
        movement("mob_hamstring_straight_leg_raise", "Elevación activa de pierna extendida", listOf("hamstring_proximal"), "leg", listOf("coxofemoral", "rodilla"), listOf("isquiosurales", "recto femoral"), "Explorar flexión de cadera con rodilla extendida", "La banda o las manos solo guían; el objetivo es que la pierna avance con control sin tirar del nervio ni levantar la pelvis.", "Boca arriba, eleva una pierna larga hasta notar tensión posterior y bájala en tres segundos manteniendo la otra pierna pesada.", 45, listOf("straight leg raise", "active hamstring stretch")),
        movement("mob_standing_hamstring_stretch", "Estiramiento de isquiosurales de pie", listOf("hamstring_proximal"), "leg", listOf("coxofemoral", "rodilla"), listOf("isquiosurales", "gemelos"), "Alargar la cadena posterior sin redondear la espalda", "La bisagra nace en la cadera y la rodilla puede flexionarse ligeramente para que la tensión no se desplace al nervio.", "Apoya el talón en una superficie baja, flexiona un poco la rodilla y lleva el pecho hacia delante desde la cadera.", 45, listOf("standing hamstring stretch"), equipment = "Apoyo bajo"),
