    private val byDiscomfort: Map<String, List<MobilityExercise>> =
        exercises.flatMap { exercise -> exercise.discomfortIds.map { it to exercise } }
            .groupBy({ it.first }, { it.second })

    private val searchIndex: Map<MobilityExercise, String> = exercises.associateWith { exercise ->
        normalizeMobilitySearch(
            listOf(
                exercise.name,
                exercise.description,
                exercise.instructions.orEmpty(),
                exercise.objective,
                exercise.bodyRegion,
                mobilityBodyRegionLabel(exercise.bodyRegion),
                exercise.joints.joinToString(" "),
                exercise.targetMuscles.joinToString(" "),
                exercise.equipment,
                exercise.level,
                exercise.aliases.joinToString(" "),
                exercise.discomfortIds.joinToString(" ") { discomfortLabel(it) },
            ).joinToString(" "),
        )
    }

    fun getMobilityForDiscomfort(discomfortId: String): List<MobilityExercise> =
        byDiscomfort[discomfortId].orEmpty()

    fun getMobilityForDiscomforts(discomfortIds: List<String>): List<MobilityExercise> =
        discomfortIds.flatMap(::getMobilityForDiscomfort).distinctBy { it.id }

    fun getAllMobilityExercises(): List<MobilityExercise> = exercises

    fun findById(id: String): MobilityExercise? = exercises.firstOrNull { it.id == id }

    /** Search by Spanish copy, anatomy, objective, discomfort or known alias. */
    fun searchMobility(query: String): List<MobilityExercise> {
        val normalized = normalizeMobilitySearch(query)
        if (normalized.isBlank()) return exercises
        val terms = normalized.split(' ').filter { it.isNotBlank() }
        return exercises.filter { exercise ->
            val haystack = searchIndex.getValue(exercise)
            terms.all { term -> haystack.contains(term) }
        }
    }

    /** Kept for callers that historically searched only by name. */
    fun searchMobilityByName(query: String): List<MobilityExercise> = searchMobility(query)
}
